Certainly! Below is a JavaScript function that takes a string representing a dot-notation path and returns all entries from an object where the nested keys match the specified values.

```javascript
function getMatchingEntries(obj, path) {
    const parts = path.split('.');
    let currentObj = obj;

    for (let i = 0; i < parts.length - 1; i++) {
        if (!currentObj || typeof currentObj !== 'object' || !Object.keys(currentObj).includes(parts[i])) {
            throw new Error(`Path '${path}' not found`);
        }

        currentObj = currentObj[parts[i]];
    }

    // Check if the last part exists
    if (typeof currentObj === 'object' && Object.keys(currentObj).includes(parts[parts.length - 1])) {
        return currentObj;
    } else {
        throw new Error(`Key '${parts[parts.length - 1]}' does not exist`);
    }
}

